#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;

    Cat(string n) : name(n) {}

    void rename(string name) {
        this->name = name;
    }
};

int main() {
    Cat c1("{name}");
    c1.rename("{newName}");
    cout << "现在叫 " << c1.name << endl;
    return 0;
}
